SET local check_function_bodies = off;

-- Removed from the pulled diff: REVOKE ALL ON SCHEMA public FROM PUBLIC / pg_database_owner and
-- COMMENT ON SCHEMA public IS NULL. They reflect drift in the hosted project's schema ownership and
-- stop a fresh local database from creating any table in public.

CREATE EXTENSION "moddatetime" SCHEMA "extensions";

CREATE EXTENSION "pgjwt" SCHEMA "extensions";

CREATE TABLE "public"."all_day_event" (
  "id"        bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title"     text,
  "sub_title" text,
  CONSTRAINT "all_day_event_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."email_whitelist" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone DEFAULT now(),
  "email"      character varying,
  CONSTRAINT "email_whitelist_email_key" UNIQUE (email),
  CONSTRAINT "email_whitelist_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."event_group" (
  "id"       bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "group_id" bigint NOT NULL,
  "event_id" bigint NOT NULL,
  CONSTRAINT "event_group_pkey" PRIMARY KEY (id, group_id, event_id)
);

CREATE TABLE "public"."event_highlighted_group" (
  "id"                   bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "highlighted_group_id" bigint NOT NULL,
  "event_id"             bigint NOT NULL,
  CONSTRAINT "event_highlighted_group_pkey" PRIMARY KEY (id, highlighted_group_id, event_id)
);

CREATE TABLE "public"."event_preset" (
  "id"                    bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"            timestamp with time zone DEFAULT now(),
  "updated_at"            timestamp with time zone DEFAULT now(),
  "start"                 timestamp with time zone,
  "is_highlighted"        boolean                  NOT NULL DEFAULT false,
  "trailer_id"            bigint,
  "event_type"            character varying        NOT NULL DEFAULT 'NORMAL'::character varying,
  "description"           text,
  "group_ids"             bigint[],
  "highlighted_group_ids" bigint[],
  CONSTRAINT "event_preset_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."event_trailer" (
  "id"   bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "text" text,
  CONSTRAINT "event_trailer_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."event" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"       timestamp with time zone DEFAULT now(),
  "updated_at"       timestamp with time zone DEFAULT now(),
  "start"            timestamp with time zone,
  "long_event_end"   timestamp with time zone,
  "is_highlighted"   boolean                  DEFAULT false,
  "trailer_id"       bigint,
  "all_day_event"    bigint,
  "multi_day_event"  bigint,
  "event_type"       character varying,
  "normal_event_end" timestamp with time zone,
  "description"      text,
  CONSTRAINT "event_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."group" (
  "id"          bigint  GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."group_duplicate_id_seq") NOT NULL,
  "letter"      text    NOT NULL,
  "highlighted" boolean NOT NULL DEFAULT false,
  CONSTRAINT "group_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."highlighted_group" (
  "id"          bigint  GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "letter"      text    NOT NULL,
  "highlighted" boolean NOT NULL DEFAULT true,
  CONSTRAINT "highlighted_group_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."multi_day_event" (
  "id"    bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title" text,
  CONSTRAINT "multi_day_event_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."new_applications" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone DEFAULT now(),
  "name"       text,
  "group"      text,
  "email"      text,
  "reason"     text,
  CONSTRAINT "new_applications_pkey" PRIMARY KEY (id)
);

CREATE TABLE "public"."profile" (
  "id"            uuid                     NOT NULL,
  "created_at"    timestamp with time zone DEFAULT now(),
  "updated_at"    timestamp with time zone DEFAULT now(),
  "avatar"        character varying        DEFAULT 'avatar.svg'::character varying,
  "username"      character varying,
  "role"          text                     DEFAULT 'user'::text,
  "group"         text                     DEFAULT ''::text,
  "calendar_type" text                     DEFAULT ''::text,
  CONSTRAINT "profile_pkey" PRIMARY KEY (id)
);

CREATE OR REPLACE FUNCTION public.check_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
BEGIN
    -- Check if the email is in the whitelist
    IF exists (SELECT 1 FROM public.email_whitelist WHERE email = new.email) THEN
        -- If the email is in the whitelist, insert the user into the users table
        RETURN new;
    ELSE
        -- If the email is not in the whitelist, return null
        RETURN null;
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.delete_claim (
  uid   uuid,
  claim text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
    BEGIN
      IF NOT is_claims_admin() THEN
          RETURN 'error: access denied';
      ELSE        
        update auth.users set raw_app_meta_data = 
          raw_app_meta_data - claim where id = uid;
        return 'OK';
      END IF;
    END;
$function$;

CREATE OR REPLACE FUNCTION public.get_claim (
  uid   uuid,
  claim text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
    DECLARE retval jsonb;
    BEGIN
      IF NOT is_claims_admin() THEN
          RETURN '{"error":"access denied"}'::jsonb;
      ELSE
        select coalesce(raw_app_meta_data->claim, null) from auth.users into retval where id = uid::uuid;
        return retval;
      END IF;
    END;
$function$;

CREATE OR REPLACE FUNCTION public.get_claims (
  uid uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
    DECLARE retval jsonb;
    BEGIN
      IF NOT is_claims_admin() THEN
          RETURN '{"error":"access denied"}'::jsonb;
      ELSE
        select raw_app_meta_data from auth.users into retval where id = uid::uuid;
        return retval;
      END IF;
    END;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_claim (
  claim text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  AS $function$
  select 
  	coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb -> 'app_metadata' -> claim, null)
$function$;

CREATE OR REPLACE FUNCTION public.get_my_claims()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  AS $function$
  select 
  	coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb -> 'app_metadata', '{}'::jsonb)::jsonb
$function$;

CREATE OR REPLACE FUNCTION public.is_claims_admin()
  RETURNS boolean
  LANGUAGE plpgsql
  AS $function$
  BEGIN
    IF session_user = 'authenticator' THEN
      --------------------------------------------
      -- To disallow any authenticated app users
      -- from editing claims, delete the following
      -- block of code and replace it with:
      -- RETURN FALSE;
      --------------------------------------------
      IF extract(epoch from now()) > coalesce((current_setting('request.jwt.claims', true)::jsonb)->>'exp', '0')::numeric THEN
        return false; -- jwt expired
      END IF; 
      IF coalesce((current_setting('request.jwt.claims', true)::jsonb)->'app_metadata'->'claims_admin', 'false')::bool THEN
        return true; -- user has claims_admin set to true
      ELSE
        return false; -- user does NOT have claims_admin set to true
      END IF;
      --------------------------------------------
      -- End of block 
      --------------------------------------------
    ELSE -- not a user session, probably being called from a trigger or something
      return true;
    END IF;
  END;
$function$;

CREATE OR REPLACE FUNCTION public.set_claim (
  uid   uuid,
  claim text,
  value jsonb
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
    BEGIN
      IF NOT is_claims_admin() THEN
          RETURN 'error: access denied';
      ELSE        
        update auth.users set raw_app_meta_data = 
          raw_app_meta_data || 
            json_build_object(claim, value)::jsonb where id = uid;
        return 'OK';
      END IF;
    END;
$function$;

ALTER TABLE "public"."event"
  ADD CONSTRAINT "event_all_day_event_fkey" FOREIGN KEY (all_day_event) REFERENCES public.all_day_event(id);

ALTER TABLE "public"."event_group"
  ADD CONSTRAINT "event_group_event_id_fkey" FOREIGN KEY (event_id) REFERENCES public.event(id);

ALTER TABLE "public"."event_highlighted_group"
  ADD CONSTRAINT "event_highlighted_group_event_id_fkey" FOREIGN KEY (event_id) REFERENCES public.event(id);

ALTER TABLE "public"."event"
  ADD CONSTRAINT "event_trailer_id_fkey" FOREIGN KEY (trailer_id) REFERENCES public.event_trailer(id);

ALTER TABLE "public"."event_preset"
  ADD CONSTRAINT "event_preset_trailer_id_fkey" FOREIGN KEY (trailer_id) REFERENCES public.event_trailer(id) ON DELETE SET NULL;

ALTER TABLE "public"."event_group"
  ADD CONSTRAINT "event_group_group_id_fkey" FOREIGN KEY (group_id) REFERENCES public."group"(id);

ALTER TABLE "public"."event_highlighted_group"
  ADD CONSTRAINT "event_highlighted_group_highlighted_group_id_fkey" FOREIGN KEY (highlighted_group_id) REFERENCES public.highlighted_group(id);

ALTER TABLE "public"."event"
  ADD CONSTRAINT "event_multi_day_event_fkey" FOREIGN KEY (multi_day_event) REFERENCES public.multi_day_event(id);

ALTER TABLE "public"."profile"
  ADD CONSTRAINT "profile_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id);

CREATE TRIGGER on_before_user_created
  BEFORE INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.check_user();

CREATE TRIGGER handle_updated_at
  BEFORE UPDATE ON public.event
  FOR EACH ROW
  EXECUTE FUNCTION extensions.moddatetime('updated_at');

CREATE POLICY "Enable read access for all authenticated users" ON "storage"."buckets"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Enable read access for all authenticated users" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING (true);

COMMENT ON COLUMN "public"."event"."event_type" IS 'can be MULTI_DAY, ALL_DAY or NORMAL';

COMMENT ON COLUMN "public"."event"."is_highlighted" IS 'if true then start is highlighted (mb: in red and underlined) and add ! after it';

COMMENT ON COLUMN "public"."event"."normal_event_end" IS 'marks the end time for normal events';

COMMENT ON COLUMN "public"."profile"."group" IS 'user picked group which is automatically shown';

COMMENT ON EXTENSION "moddatetime" IS 'functions for tracking last modification time';

COMMENT ON EXTENSION "pgjwt" IS 'JSON Web Token API for Postgresql';

COMMENT ON TABLE "public"."event_trailer" IS 'this contains event trailers like "!" or "- EKSAM"';

COMMENT ON TABLE "public"."new_applications" IS 'holds new applications sent by apply-to-club form';

